begin;
insert into public.ce_course3_resources(id,data) values
('course3_module4_pdf','{"base64": "", "sha256": "b65305d2c3aad20813316abdf691052b2ea1383c1ac0dc6e0d5eedd6af9a0e7f", "filename": "CE_HALO_Course3_Module04_Standards_of_Care_Learner_FINAL.pdf", "mime_type": "application/pdf"}'::jsonb),
('course3_module4_questions','[{"module_id": "course_3_module_4", "question_id": "course_3_module_4_q01", "question_number": 1, "stem": "Which statement best describes the relationship between anesthesia standards of care and clinical judgment?", "choice_a": "Standards define minimum expectations; clinical judgment tailors and often exceeds them based on patient, procedure, and setting", "choice_b": "Clinical judgment overrides standards whenever the anesthesia professional believes it is appropriate", "choice_c": "Standards apply only when a facility formally adopts them as policy", "choice_d": "Standards replace clinical judgment because they define exactly what must be done in every case", "correct_choice": "a", "rationale": "Standards define the floor of safe, competent practice. Clinical judgment is required to tailor care to the individual patient, procedure, and setting, and often to exceed the minimum expectation. [Standard]", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["b", "c"], "remaining_choices": ["a", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_3_module_4", "question_id": "course_3_module_4_q02", "question_number": 2, "stem": "How many standards are included in the AANA Standards for Nurse Anesthesia Practice?", "choice_a": "12", "choice_b": "14", "choice_c": "10", "choice_d": "16", "correct_choice": "b", "rationale": "The AANA Standards for Nurse Anesthesia Practice contain 14 standards addressing patient rights, preanesthesia assessment, planning, informed consent, equipment, plan implementation, patient status, positioning/safety, monitoring/alarms/documentation, infection prevention, transfer of care, quality improvement, culture of safety, and wellness. [Standard]", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "c"], "remaining_choices": ["b", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_3_module_4", "question_id": "course_3_module_4_q03", "question_number": 3, "stem": "Which AANA standard specifically requires that alarms be active and audible when monitoring devices are used?", "choice_a": "Standard 13 (Culture of Safety)", "choice_b": "Standard 7 (Patient Status)", "choice_c": "Standard 9 (Monitoring, Alarms, and Documentation)", "choice_d": "Standard 5 (Equipment)", "correct_choice": "c", "rationale": "AANA Standard 9 addresses monitoring, alarms, and documentation and specifically requires that alarms be active and audible whenever monitoring devices are used. [Standard]", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "b"], "remaining_choices": ["c", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_3_module_4", "question_id": "course_3_module_4_q04", "question_number": 4, "stem": "The ASA Standards for Basic Anesthetic Monitoring explicitly do NOT apply to which of the following?", "choice_a": "Monitored anesthesia care (MAC)", "choice_b": "General anesthesia", "choice_c": "Regional anesthesia", "choice_d": "Labor analgesia", "correct_choice": "d", "rationale": "The ASA basic monitoring standards apply to general anesthesia, regional anesthesia, and MAC. They explicitly do not apply to labor analgesia, which is governed by separate obstetric anesthesia guidance. [Standard]", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "b"], "remaining_choices": ["c", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_3_module_4", "question_id": "course_3_module_4_q05", "question_number": 5, "stem": "Under ASA Standard II, arterial blood pressure and heart rate must be determined and evaluated at what minimum interval during anesthesia?", "choice_a": "At least every 5 minutes unless clinically impractical", "choice_b": "At least every 15 minutes", "choice_c": "At least every 10 minutes", "choice_d": "Every minute", "correct_choice": "a", "rationale": "ASA Standard II requires arterial blood pressure and heart rate to be determined and evaluated at least every 5 minutes unless clinically impractical. [Standard]", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["b", "c"], "remaining_choices": ["a", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_3_module_4", "question_id": "course_3_module_4_q06", "question_number": 6, "stem": "During general anesthesia with an advanced airway, ASA monitoring standards require:", "choice_a": "Only pulse oximetry", "choice_b": "Verification of correct placement and continuous quantitative end-tidal CO₂ (capnography) throughout the anesthetic", "choice_c": "ECG monitoring only, unless capnography is available", "choice_d": "Capnography only during the first 30 minutes", "correct_choice": "b", "rationale": "ASA Standard II requires verification of correct endotracheal or supraglottic airway placement and continuous quantitative end-tidal CO₂ monitoring throughout the anesthetic when an advanced airway is used. [Standard]", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "c"], "remaining_choices": ["b", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_3_module_4", "question_id": "course_3_module_4_q07", "question_number": 7, "stem": "Per ASA Standard I, when a brief absence of the primary anesthesia professional is required during a case:", "choice_a": "The case must be paused", "choice_b": "The anesthesia workstation alarms are sufficient replacement", "choice_c": "A qualified individual must assume responsibility, and the arrangement and rationale should be documented", "choice_d": "Unqualified personnel may monitor the patient temporarily", "correct_choice": "c", "rationale": "ASA Standard I requires that qualified anesthesia personnel be present throughout the anesthetic; if a brief absence is clinically justified, a qualified individual must assume responsibility and the arrangement should be documented. [Standard]", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "b"], "remaining_choices": ["c", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_3_module_4", "question_id": "course_3_module_4_q08", "question_number": 8, "stem": "Which statement best distinguishes a professional ''standard'' from a professional ''guideline''?", "choice_a": "Standards apply only to physicians; guidelines apply to nurses", "choice_b": "Standards and guidelines have identical legal weight", "choice_c": "Guidelines are always more current than standards", "choice_d": "Standards describe minimum expected behavior and are enforceable through credentialing and disciplinary action; guidelines are evidence-based recommendations that allow more clinical latitude", "correct_choice": "d", "rationale": "Standards describe minimum expected performance and are enforceable through peer review, credentialing, and licensure. Guidelines are evidence-based recommendations that allow greater latitude for clinical judgment. [Legal]", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "b"], "remaining_choices": ["c", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_3_module_4", "question_id": "course_3_module_4_q09", "question_number": 9, "stem": "A CRNA is deposed in a malpractice case. Which of the following documents is MOST likely to be introduced by an expert witness to define the standard of care owed to the plaintiff?", "choice_a": "The AANA Standards for Nurse Anesthesia Practice and the ASA Standards for Basic Anesthetic Monitoring", "choice_b": "The hospital''s marketing brochure", "choice_c": "A general internet search result", "choice_d": "The CRNA''s personal continuing education transcript", "correct_choice": "a", "rationale": "AANA and ASA standards are commonly cited by expert witnesses in malpractice litigation to define the reasonably prudent anesthesia professional''s conduct. [Legal]", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["b", "c"], "remaining_choices": ["a", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_3_module_4", "question_id": "course_3_module_4_q10", "question_number": 10, "stem": "A CRNA deviates from a monitoring standard during an emergency. What is the correct approach to documentation?", "choice_a": "Document only that an ''emergency occurred''", "choice_b": "Document the specific standard affected, the clinical reason for deviation, and any mitigating actions taken", "choice_c": "Wait 30 days and then document from memory", "choice_d": "Do not document the deviation to avoid legal exposure", "correct_choice": "b", "rationale": "Both AANA and ASA standards acknowledge that documented, justified deviations are consistent with standards-based care. Deviations should be documented with clinical rationale and mitigating actions. [Documentation]", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "c"], "remaining_choices": ["b", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_3_module_4", "question_id": "course_3_module_4_q11", "question_number": 11, "stem": "Which federal regulation establishes anesthesia service requirements for Medicare-participating hospitals?", "choice_a": "45 CFR §164.502", "choice_b": "42 USC §1395dd (EMTALA)", "choice_c": "42 CFR §482.52", "choice_d": "21 CFR §1301.11", "correct_choice": "c", "rationale": "42 CFR §482.52 is the Anesthesia Services Condition of Participation for hospitals. §485.639 covers critical access hospitals; §416.42 covers ambulatory surgical centers. [Regulatory]", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "b"], "remaining_choices": ["c", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_3_module_4", "question_id": "course_3_module_4_q12", "question_number": 12, "stem": "Which of the following is NOT among the four physiologic domains addressed by ASA Standard II (continuous physiologic evaluation)?", "choice_a": "Oxygenation", "choice_b": "Circulation", "choice_c": "Ventilation", "choice_d": "Bispectral index (BIS)", "correct_choice": "d", "rationale": "ASA Standard II addresses oxygenation, ventilation, circulation, and temperature. Bispectral index (BIS) is not a required element of basic anesthetic monitoring. [Standard]", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "b"], "remaining_choices": ["c", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_3_module_4", "question_id": "course_3_module_4_q13", "question_number": 13, "stem": "A CRNA is preparing to add anesthesia services at an office-based plastic surgery practice. Which of the following is the MOST complete pre-service verification list?", "choice_a": "Confirm governance, patient selection criteria, staffing, equipment, recovery capability, transfer agreement, MH preparedness when triggering agents are used, controlled substance management, infection prevention, and backup power/oxygen", "choice_b": "Verify the facility''s marketing plan", "choice_c": "Confirm oxygen supply only", "choice_d": "Confirm only the surgeon''s board certification", "correct_choice": "a", "rationale": "Per AANA Office Based Anesthesia guidance and ASA Statement on Office-Based Anesthesia (2024), CRNAs should verify governance, patient selection, staffing, equipment, recovery capability, transfer agreement, MH preparedness, controlled-substance management, infection prevention, and backup power/oxygen. [Application]", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["b", "c"], "remaining_choices": ["a", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_3_module_4", "question_id": "course_3_module_4_q14", "question_number": 14, "stem": "Which of the following is the MOST accurate description of the ASA monitoring standards'' relationship to nonoperating room anesthesia (NORA)?", "choice_a": "Only anesthesiologists may practice in NORA locations", "choice_b": "ASA basic monitoring standards apply to NORA locations; environmental considerations (space, power, communication, rescue) add operational requirements per the ASA Statement on Nonoperating Room Anesthetizing Locations", "choice_c": "NORA sites are exempt from capnography requirements", "choice_d": "ASA monitoring standards do not apply outside the operating room", "correct_choice": "b", "rationale": "The ASA basic monitoring standards apply to NORA. The ASA Statement on Nonoperating Room Anesthetizing Locations (2023) adds environmental and operational expectations regarding space, oxygen supply, suction, power, lighting, communication, and rescue capability. [Application]", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "c"], "remaining_choices": ["b", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_3_module_4", "question_id": "course_3_module_4_q15", "question_number": 15, "stem": "Per the 2024 ASRA/ESRA Fourth Consensus Practice Advisory on local anesthetic systemic toxicity (LAST), the initial intravenous lipid emulsion bolus for LAST treatment is:", "choice_a": "5 mL/kg of 20% lipid emulsion over 10 minutes", "choice_b": "0.5 mL/kg of 10% lipid emulsion", "choice_c": "1.5 mL/kg of 20% lipid emulsion over 2–3 minutes, followed by 0.25 mL/kg/min infusion", "choice_d": "Lipid emulsion is not recommended for LAST", "correct_choice": "c", "rationale": "Per the 2024 ASRA/ESRA update, initial treatment includes 20% intravenous lipid emulsion 1.5 mL/kg bolus over 2–3 minutes, followed by infusion at 0.25 mL/kg/min; bolus may be repeated for persistent cardiovascular instability. [Application]", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "b"], "remaining_choices": ["c", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_3_module_4", "question_id": "course_3_module_4_q16", "question_number": 16, "stem": "During regional anesthesia, minimum recommended post-injection monitoring for LAST recognition is:", "choice_a": "5 minutes", "choice_b": "15 minutes", "choice_c": "1 hour, but only for high-risk patients", "choice_d": "At least 30 minutes with continuous physiologic monitoring in a monitored setting", "correct_choice": "d", "rationale": "Per current ASRA/ESRA guidance, patients should be monitored for at least 30 minutes after the final local anesthetic injection with continuous physiologic monitoring in a monitored setting, because LAST may present with delayed onset. [Application]", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "b"], "remaining_choices": ["c", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_3_module_4", "question_id": "course_3_module_4_q17", "question_number": 17, "stem": "Which statement about obstetric anesthesia is MOST consistent with current AANA and ASA guidance?", "choice_a": "ASA basic monitoring standards are not intended to define labor analgesia monitoring; obstetric-specific guidance and facility protocols apply, with core principles of assessment, vigilance, documentation, and emergency readiness maintained", "choice_b": "CRNAs may not provide labor analgesia in any state", "choice_c": "ASA basic monitoring standards fully define labor analgesia monitoring requirements", "choice_d": "Neuraxial techniques do not require informed consent", "correct_choice": "a", "rationale": "ASA basic monitoring standards explicitly do not apply to labor analgesia. AANA Obstetric Anesthesia and Analgesia Practice Considerations (2023) and setting-specific guidance govern, while core standards principles remain in effect. [Application]", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["b", "c"], "remaining_choices": ["a", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_3_module_4", "question_id": "course_3_module_4_q18", "question_number": 18, "stem": "A CRNA is called to a mass casualty event in which conventional anesthesia care cannot be maintained. Which of the following BEST describes standards-based practice under crisis standards of care?", "choice_a": "The CRNA should refuse to work until conventional standards can be restored", "choice_b": "Crisis standards allow triage-based resource allocation, altered staffing, and modified documentation, but core safety principles and professional accountability remain; deviations should be documented when feasible", "choice_c": "All professional accountability is suspended", "choice_d": "Documentation is not required during crisis events", "correct_choice": "b", "rationale": "Crisis standards of care permit operational modifications under declared crisis conditions but do not eliminate professional accountability. Core safety and, when feasible, contemporaneous documentation of deviations should continue. [Application]", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "c"], "remaining_choices": ["b", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_3_module_4", "question_id": "course_3_module_4_q19", "question_number": 19, "stem": "A facility''s anesthesia policy adopts AANA and ASA standards by reference. What is the legal effect for a CRNA credentialed at that facility?", "choice_a": "Only the medical staff bylaws are enforceable", "choice_b": "The standards apply only to physicians, not to CRNAs", "choice_c": "The facility policy makes AANA and ASA standards locally enforceable through credentialing and disciplinary action", "choice_d": "The standards remain purely aspirational because they are external to the facility", "correct_choice": "c", "rationale": "When a facility policy adopts external standards, those standards become locally binding through credentialing, peer review, and disciplinary processes. [Legal]", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "b"], "remaining_choices": ["c", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_3_module_4", "question_id": "course_3_module_4_q20", "question_number": 20, "stem": "Which of the following is a specific requirement of ASA Standard I regarding qualified anesthesia personnel?", "choice_a": "Personnel may leave the room during stable maintenance phases with no documentation required", "choice_b": "Personnel must hold board certification in anesthesiology", "choice_c": "Only physicians may be present during general anesthesia", "choice_d": "Qualified anesthesia personnel remain present in the room throughout general anesthesia, regional anesthesia, and monitored anesthesia care, unless a temporary absence is clinically justified with safe monitoring arrangements", "correct_choice": "d", "rationale": "ASA Standard I requires that qualified anesthesia personnel be present in the room throughout general anesthesia, regional anesthesia, and MAC unless a brief absence is clinically justified with safe monitoring arrangements. [Standard]", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "b"], "remaining_choices": ["c", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_3_module_4", "question_id": "course_3_module_4_q21", "question_number": 21, "stem": "AANA Standards 13 (Culture of Safety) and 14 (Wellness) were elevated as formal standards because:", "choice_a": "Human factors — including fatigue, stress, burnout, and impairment — measurably degrade patient safety, and organizational culture affects error reporting, systems learning, and outcomes", "choice_b": "Wellness and safety culture are optional considerations only", "choice_c": "These standards apply only to trainees", "choice_d": "The AANA needed to lengthen the standards document", "correct_choice": "a", "rationale": "Human factors research and patient safety literature demonstrate that clinician wellness and safety culture directly affect performance, reporting, and outcomes, which supported formal elevation of these domains within the AANA standards. [Standard]", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["b", "c"], "remaining_choices": ["a", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_3_module_4", "question_id": "course_3_module_4_q22", "question_number": 22, "stem": "Which of the following is the correct interpretation of the terms ''continual'' and ''continuous'' in the ASA monitoring standards?", "choice_a": "''Continual'' means uninterrupted electronic monitoring only", "choice_b": "''Continual'' means repeated regularly and frequently in steady rapid succession, while ''continuous'' means prolonged without interruption at any time", "choice_c": "The terms are interchangeable", "choice_d": "''Continuous'' means every 15 minutes", "correct_choice": "b", "rationale": "Per the ASA monitoring standards, ''continual'' means repeated regularly and frequently in steady rapid succession, and ''continuous'' means prolonged without any interruption at any time. Pulse oximetry is continuous; noninvasive blood pressure is continual. [Standard]", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "c"], "remaining_choices": ["b", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_3_module_4", "question_id": "course_3_module_4_q23", "question_number": 23, "stem": "A CRNA discovers that the pulse oximeter in a NORA suite is not functioning immediately before beginning a MAC case. What is the correct response consistent with AANA and ASA standards?", "choice_a": "Substitute capnography for pulse oximetry indefinitely", "choice_b": "Proceed with the case and monitor blood oxygenation clinically", "choice_c": "Delay the case until a functional pulse oximeter is available; AANA Standard 5 (Equipment) and ASA basic monitoring require functioning pulse oximetry for these anesthetics", "choice_d": "Ask the proceduralist to determine whether to proceed", "correct_choice": "c", "rationale": "Both AANA Standard 5 (Equipment) and ASA basic monitoring standards require pulse oximetry for general anesthesia, regional anesthesia, and MAC. The case should be delayed until functional monitoring is available. [Application]", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "b"], "remaining_choices": ["c", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_3_module_4", "question_id": "course_3_module_4_q24", "question_number": 24, "stem": "Which of the following documents specifically addresses accreditation expectations for anesthesia care in U.S. hospitals?", "choice_a": "USPSTF recommendations", "choice_b": "OSHA General Duty Clause", "choice_c": "FDA Center for Devices and Radiological Health guidance", "choice_d": "The Joint Commission Comprehensive Accreditation Manual (PC.03.01.01 through PC.03.01.07)", "correct_choice": "d", "rationale": "The Joint Commission''s Comprehensive Accreditation Manual for Hospitals contains anesthesia care standards PC.03.01.01 through PC.03.01.07 covering preanesthesia assessment, informed consent, monitoring, and postanesthesia care. [Regulatory]", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "b"], "remaining_choices": ["c", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_3_module_4", "question_id": "course_3_module_4_q25", "question_number": 25, "stem": "For a routine general anesthetic, which of the following is the MOST accurate summary of the CRNA''s alignment with both AANA and ASA standards?", "choice_a": "Meet the ASA basic monitoring floor for oxygenation, ventilation, circulation, and temperature; and satisfy AANA standards across assessment, planning, consent, equipment, plan implementation, monitoring/alarms/documentation, transfer, and related professional responsibilities", "choice_b": "Meet the AANA standards and disregard the ASA standards because they were written for physicians", "choice_c": "Follow ASA only when the case is billed to Medicare", "choice_d": "Follow whichever framework the surgeon prefers", "correct_choice": "a", "rationale": "AANA and ASA standards are complementary. CRNAs are expected to meet the ASA monitoring floor and the full AANA professional practice framework for every routine general anesthetic. [Standard]", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["b", "c"], "remaining_choices": ["a", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}]'::jsonb)
on conflict(id) do update set data=excluded.data;
do $$ begin
assert (select encode(sha256(decode(data->>'base64','base64')),'hex')=data->>'sha256' from public.ce_course3_resources where id='course3_module4_pdf'),'PDF hash mismatch';
assert (select released=false from public.ce_course3_catalog where id='1047243'),'Course must remain staged';
end $$;
commit;